html = open(ROOT + '/otchet/shablon.html').read().replace('/*DATA*/null', json.dumps(DATA, ensure_ascii=False))
open(ROOT + '/otchet/index.html', 'w').write(html)
print('ok', len(products), 'товаров,', sum(len(L['queries']) for L in lines), 'фраз в линейках')
